async function ok() { return 42; }
async function fail() { throw new Error('boom'); }
async function main() {
  try {
    var v = await ok();
    console.log('await ok:', v);
    await fail();
  } catch (e) {
    console.log('caught:', e.message);
  } finally {
    console.log('finally ran');
  }
}
main();
